#include <vector>

std::vector<bool> features() {
    return {false, true, false, true, false, true};
}

// A function to demonstrate the issue
void process() {
    bool priority_explicit = features()[5]; // OK: type is bool, value is true

    auto priority_auto = features()[5];   // DANGER: type is std::vector<bool>::reference
                                          // It holds a pointer into the temporary vector
                                          // returned by features(), which is now destroyed.

    // Using priority_auto here is undefined behavior.
}
